//! Circuit selection on complete synthetic documents
//! (tests/data/documents.json, generated by `eid-vectors documents`): each
//! must select exactly the circuits it was built for, against a registry
//! holding only its mock CSCA; tampered or expired documents must be refused.

use csca_registry::output::Registry;
use csca_registry::registry::Builder;
use eid_prover::select;
use serde_json::Value;

fn documents() -> Vec<Value> {
    let text = std::fs::read_to_string(concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/tests/data/documents.json"
    ))
    .expect("documents.json");
    let v: Value = serde_json::from_str(&text).expect("json");
    v["documents"].as_array().expect("documents").clone()
}

fn bytes(d: &Value, field: &str) -> Vec<u8> {
    hex::decode(d[field].as_str().expect(field)).expect("hex")
}

fn registry(cscas: &[Vec<u8>]) -> Registry {
    let mut b = Builder::default();
    for (i, c) in cscas.iter().enumerate() {
        b.add_certificates(&format!("mock-{i}.der"), c);
    }
    b.finish().expect("registry")
}

fn date(d: &Value) -> i64 {
    d["date"].as_i64().expect("date")
}

#[test]
fn selects_the_circuits_each_document_was_built_for() {
    for d in documents() {
        let reg = registry(&[bytes(&d, "csca")]);
        let s = select(&reg, &bytes(&d, "ef_sod"), &bytes(&d, "dg1"), date(&d))
            .unwrap_or_else(|e| panic!("{}: {e:#}", d["name"]));
        let e = &d["expect"];
        assert_eq!(s.country, e["country"].as_str().unwrap(), "{}", d["name"]);
        assert_eq!(s.dsc, e["dsc"].as_str().unwrap(), "{}", d["name"]);
        assert_eq!(s.sod, e["sod"].as_str().unwrap(), "{}", d["name"]);
        assert_eq!(s.envelope, e["envelope"].as_str().unwrap(), "{}", d["name"]);
    }
}

#[test]
fn the_csca_is_found_among_other_keys() {
    let docs = documents();
    let all: Vec<Vec<u8>> = docs.iter().map(|d| bytes(d, "csca")).collect();
    let reg = registry(&all);
    for d in &docs {
        select(&reg, &bytes(d, "ef_sod"), &bytes(d, "dg1"), date(d))
            .unwrap_or_else(|e| panic!("{}: {e:#}", d["name"]));
    }
}

fn refusal(d: &Value, reg: &Registry, sod: &[u8], dg1: &[u8], at: i64) -> String {
    match select(reg, sod, dg1, at) {
        Ok(s) => panic!("{}: accepted as {s:?}", d["name"]),
        Err(e) => format!("{e:#}"),
    }
}

#[test]
fn refuses_tampered_expired_or_unregistered_documents() {
    let docs = documents();
    let d = &docs[0];
    let (sod, dg1) = (bytes(d, "ef_sod"), bytes(d, "dg1"));
    let reg = registry(&[bytes(d, "csca")]);

    let mut tampered = dg1.clone();
    tampered[20] ^= 0x01;
    assert!(refusal(d, &reg, &sod, &tampered, date(d)).contains("DG1 does not match"));

    assert!(refusal(d, &reg, &sod, &dg1, 2_100_000_000).contains("expired"));

    let other = registry(&[bytes(&docs[1], "csca")]);
    assert!(refusal(d, &other, &sod, &dg1, date(d)).contains("no CSCA"));

    let mut bad_sig = sod.clone();
    let last = bad_sig.len() - 1;
    bad_sig[last] ^= 0x01;
    assert!(refusal(d, &reg, &bad_sig, &dg1, date(d)).contains("SOD signature"));
}

#[test]
fn builds_inputs_for_the_selected_circuits() {
    for d in documents() {
        let reg = registry(&[bytes(&d, "csca")]);
        let p = eid_prover::Params {
            dsc_salt: "1".into(),
            sod_salt: "2".into(),
            date: date(&d),
            context: "3".into(),
            scope: "6".into(),
            viewers: [("7".to_string(), "8".to_string())],
            ephemeral: "4".into(),
            key: "5".into(),
        };
        let w = eid_prover::witnesses(&reg, &bytes(&d, "ef_sod"), &bytes(&d, "dg1"), &p)
            .unwrap_or_else(|e| panic!("{}: {e:#}", d["name"]));
        assert!(w
            .dsc
            .contains(&format!("root = \"{}\"", reg.commitment.root)));
        assert!(w.sod.contains("dsc_salt = \"1\"") && w.sod.contains("salt = \"2\""));
        assert!(w.envelope.contains("sod_salt = \"2\"") && w.envelope.contains("context = \"3\""));
        assert!(w.envelope.contains("scope = \"6\""));
    }
}
